export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/hbuf
rm -rf $D; mkdir -p $D; cd $D || exit 1
cat > p.b64 <<'EOS'

EOS
base64 -d p.b64 > p.zip && unzip -oq p.zip -d $D
for t in d0 d1 d2; do
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1
  if grep -q "DONE_$t" $t.log; then echo "OK $t | $(grep CHK_BH $t.log | head -1) | pips=$(grep -c . $t.pips 2>/dev/null || echo 0)"; else echo "FAIL $t"; grep -E "ERROR|Aborted" $t.log | head -4; fi
done
tar czf /tmp/hbuf_out.tgz *.bit *.pips *.log 2>/dev/null || true
echo BUFDONE
